def solve(inputs, readings):
    parcels = inputs['parcels']
    service = readings['service']

    total_cents = 0
    heaviest = parcels[0]
    for parcel in parcels:
        grams = parcel['grams']
        if grams > heaviest['grams']:
            heaviest = parcel

        if grams <= 100:
            base_cents = 85
        elif grams <= 500:
            base_cents = 155
        elif grams <= 1000:
            base_cents = 240
        else:
            extra_blocks = (grams - 1000 + 499) // 500
            base_cents = 240 + 75 * extra_blocks

        if service == 'express':
            price_cents = (3 * base_cents + 1) // 2
        elif service == 'tracked':
            price_cents = base_cents + 120
        else:
            price_cents = base_cents
        total_cents += price_cents

    total = f'{total_cents // 100}.{total_cents % 100:02d}'
    return f"{service}: total {total} | {len(parcels)} parcels | heaviest {heaviest['id']}"

def solve(inputs, readings):
    items = inputs['items']
    diners = inputs['diners']
    service = readings['service']

    subtotal = 0
    for item in items:
        pounds, pennies = item.split('.')
        subtotal += int(pounds) * 100 + int(pennies)

    if service == 'poor':
        tip = 0
    elif service == 'good':
        tip = (subtotal + 4) // 8
    else:
        tip = (3 * subtotal + 10) // 20

    total = subtotal + tip
    each = (total + diners - 1) // diners
    extra = each * diners - total

    def format_money(cents):
        return str(cents // 100) + '.' + str(cents % 100).zfill(2)

    return 'total ' + format_money(total) + ' | each ' + format_money(each) + ' | extra ' + format_money(extra)
